# 二进制分组优化
items = []  # (weight, value) 拆分后的0-1背包物品
for i in 1..n:
  c = 1
  while c < k[i]:
    items.append((c*w[i], c*v[i]))
    k[i] -= c; c *= 2
  items.append((k[i]*w[i], k[i]*v[i]))
# 标准0-1背包
for item in items:
  for j in W down to item.weight:
    f[j] = max(f[j], f[j-item.weight] + item.value)
